const topic = $items('Select Topic and Idempotency Seed', 0, 0)[0].json;
const response = $input.first().json;
const raw = response?.choices?.[0]?.message?.content;
if (!raw) {
  throw new Error('Missing OpenAI content payload.');
}
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error('OpenAI payload was not valid JSON.');
}
const title = String(parsed.title || '').trim();
const excerpt = String(parsed.excerpt || '').trim();
const content = String(parsed.content || '').trim();
if (!title || !excerpt || !content) {
  throw new Error('OpenAI payload missing title, excerpt, or content.');
}
const slugBase = String(parsed.slug || title)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');
const finalSlug = `${slugBase}-${topic.dateToken}`;
const tags = Array.isArray(parsed.tags) && parsed.tags.length
  ? parsed.tags.map((tag) => String(tag).trim().toLowerCase()).filter(Boolean)
  : topic.tags;
const seoImage = `https://res.cloudinary.com/dtmh3eypz/image/upload/c_fill,g_auto,w_1200,h_630/f_auto/q_auto/${topic.imagePublicId}`;
const publishBody = {
  section: 'articles',
  sourceBlog: topic.sourceBlog,
  sourceChannel: topic.sourceChannel,
  dryRun: true,
  requestId: `${topic.sourceBlog}-${finalSlug}`,
  idempotencyKey: `${topic.sourceBlog}-${finalSlug}`,
  frontmatter: {
    title,
    slug: finalSlug,
    section: 'articles',
    category: topic.category,
    tags,
    description: excerpt,
    summary: excerpt,
    access: 'public',
    status: 'published',
    publishedAt: topic.dateIso,
    updatedAt: topic.dateIso,
    author: topic.author,
    seoTitle: title,
    seoDescription: excerpt,
    seoImage,
    publishWindow: '05:05 America/New_York',
    sourceChannel: topic.sourceChannel,
    sourceBlog: topic.sourceBlog,
    slugBase,
    assetIds: [topic.imagePublicId],
    assetRefs: [`image:${topic.imagePublicId}`]
  },
  content
};
return [{ json: { publishBody } }];
